<?php
namespace App\Http\Controllers;
use App\Models\Customer; use App\Models\Enquiry; use App\Models\Service; use App\Support\Workspace; use Illuminate\Http\Request;
class EnquiryController extends Controller {
    public function index(Request $request) { $b=Workspace::business($request); $query=Enquiry::where('business_id',$b->id)->with(['customer','service'])->latest('received_at'); if($request->filled('status')) $query->where('status',$request->string('status')); if($request->filled('q')) $query->whereHas('customer',fn($q)=>$q->where('name','like','%'.$request->q.'%')->orWhere('email','like','%'.$request->q.'%')); return view('enquiries.index',['enquiries'=>$query->paginate(20)->withQueryString(),'business'=>$b]); }
    public function create(Request $request) { $b=Workspace::business($request); return view('enquiries.create',['services'=>$b->services()->where('active',true)->get()]); }
    public function store(Request $request) { $b=Workspace::business($request); $data=$this->validated($request); if(!empty($data['service_id'])) abort_unless($b->services()->whereKey($data['service_id'])->exists(),404); $customer=Customer::updateOrCreate(['business_id'=>$b->id,'email'=>$data['email']?:null,'phone'=>$data['phone']?:null],['name'=>$data['customer_name'],'address'=>$data['property_address']??null]); $enquiry=Enquiry::create(collect($data)->except(['customer_name','email','phone'])->all()+['business_id'=>$b->id,'customer_id'=>$customer->id,'source'=>'manual']); $this->log($enquiry,'enquiry_created'); return redirect()->route('enquiries.show',$enquiry)->with('status','Enquiry added.'); }
    public function show(Request $request, Enquiry $enquiry) { $b=Workspace::business($request); Workspace::assertBusiness($enquiry,$b); return view('enquiries.show',['enquiry'=>$enquiry->load(['customer','service','quotes.items','quotes.events']),'services'=>$b->services()->where('active',true)->get()]); }
    public function update(Request $request, Enquiry $enquiry) { $b=Workspace::business($request); Workspace::assertBusiness($enquiry,$b); $data=$request->validate(['status'=>'required|in:new,replied,quote_sent,follow_up_needed,booked,lost','follow_up_at'=>'nullable|date']); $enquiry->update($data); $this->log($enquiry,'status_changed',$data); return back()->with('status','Enquiry updated.'); }
    private function validated(Request $r): array { return $r->validate(['customer_name'=>'required|string|max:120','email'=>'nullable|email|max:255','phone'=>'nullable|string|max:50','service_id'=>'nullable|integer','property_type'=>'nullable|string|max:100','property_address'=>'nullable|string|max:2000','bedrooms'=>'nullable|integer|min:0|max:99','bathrooms'=>'nullable|integer|min:0|max:99','preferred_date'=>'nullable|date','notes'=>'nullable|string|max:5000']); }
    private function log(Enquiry $e,string $action,array $properties=[]): void { \App\Models\ActivityLog::create(['business_id'=>$e->business_id,'user_id'=>auth()->id(),'subject_type'=>$e::class,'subject_id'=>$e->id,'action'=>$action,'properties'=>$properties]); }
}
